package com.dramastudio.template;
import com.fasterxml.jackson.databind.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class PromptTemplateEngine {
 private final ObjectMapper json; public PromptTemplateEngine(ObjectMapper j){json=j;}
 public record Resolved(Map<String,Object> values,Map<String,String> sources,String prompt,String negativePrompt){}
 @SuppressWarnings("unchecked") public Resolved resolve(Map<String,Object> definition,Map<String,Object> overrides,Map<String,Object> upstream){var values=new LinkedHashMap<String,Object>();var sources=new LinkedHashMap<String,String>();var rendered=new ArrayList<String>();for(var raw:(List<Map<String,Object>>)definition.getOrDefault("sections",List.of())){String key=(String)raw.get("key");Object value=null;String source="DEFAULT";boolean allowEmpty=Boolean.TRUE.equals(raw.get("allowEmptyOverride"));if(overrides.containsKey(key)&&valid(overrides.get(key),allowEmpty)){value=overrides.get(key);source="USER";}else if(upstream.containsKey(key)&&valid(upstream.get(key),false)){value=upstream.get(key);source="UPSTREAM";}else value=raw.get("defaultValue");if(Boolean.TRUE.equals(raw.get("required"))&&!valid(value,true))throw new IllegalArgumentException("Missing required template variable: "+key);values.put(key,value);sources.put(key,source);if(value!=null)rendered.add(Objects.toString(raw.getOrDefault("label",key))+": "+(value instanceof Collection<?> c?String.join(Objects.toString(raw.getOrDefault("joiner",", ")),c.stream().map(Objects::toString).toList()):value));}Map<String,Object> neg=(Map<String,Object>)definition.getOrDefault("negativePrompt",Map.of());Object negative=overrides.containsKey("negative_prompt")?overrides.get("negative_prompt"):upstream.getOrDefault("negative_prompt",neg.getOrDefault("defaultValue",""));return new Resolved(values,sources,String.join("\n",rendered),Objects.toString(negative,""));}
 private boolean valid(Object v,boolean allowEmpty){return v!=null&&(allowEmpty||!(v instanceof String s)||!s.isBlank());}
 public Map<String,Object> parse(String s){try{return json.readValue(s,new com.fasterxml.jackson.core.type.TypeReference<>(){});}catch(Exception e){throw new IllegalArgumentException("Invalid template JSON",e);}}
}
